#!/usr/bin/env python3
"""Refresh committed C++ tables after an explicitly reviewed metadata change."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
scenes = json.loads((ROOT / 'scenario_manifest.json').read_text())['scenarios']
assert len({s['id'] for s in scenes}) == len(scenes)
(ROOT / 'scenario_table.h').write_text(
    '// Generated by tools/sync_tables.py.\nstatic const Scenario kScenarios[]={\n' +
    ''.join('  {' + ', '.join(json.dumps(s[k]) for k in
        ('id', 'path', 'assertion_trace')) + ', ' + str(s.get('fixed_rowid_generator', False)).lower() + '},\n' for s in scenes) + '};\n')
public = json.loads((ROOT / 'public_abi.json').read_text())['public']
(ROOT / 'public_abi.h').write_text(
    '// Generated by tools/sync_tables.py.\nstatic const char *const kPublicAbi[]={\n' +
    ''.join('  ' + json.dumps(s) + ',\n' for s in public) + '};\n')
